<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT id,name FROM client_projects WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Project not found.');}$dir=__DIR__.'/../storage/project-documents/'.$id;if(!is_dir($dir))mkdir($dir,0750,true);if($_SERVER['REQUEST_METHOD']==='POST'){if(!isset($_FILES['document'])||$_FILES['document']['error']!==UPLOAD_ERR_OK)exit('Upload failed.');$f=$_FILES['document'];if($f['size']>10*1024*1024)exit('Maximum file size is 10MB.');$allowed=['pdf'=>'application/pdf','png'=>'image/png','jpg'=>'image/jpeg','jpeg'=>'image/jpeg','webp'=>'image/webp','doc'=>'application/msword','docx'=>'application/vnd.openxmlformats-officedocument.wordprocessingml.document','xls'=>'application/vnd.ms-excel','xlsx'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','zip'=>'application/zip'];$ext=strtolower(pathinfo($f['name'],PATHINFO_EXTENSION));$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$ext])||$allowed[$ext]!==$mime)exit('File type not allowed.');$stored=bin2hex(random_bytes(16)).'.'.$ext;$path=$dir.'/'.$stored;if(!move_uploaded_file($f['tmp_name'],$path))exit('Could not store file.');$title=trim($_POST['title']??pathinfo($f['name'],PATHINFO_FILENAME));$visibility=($_POST['visibility']??'client')==='admin'?'admin':'client';$q=$db->prepare('INSERT INTO project_documents(project_id,title,file_path,file_name,mime_type,file_size,visibility) VALUES(?,?,?,?,?,?,?)');$q->execute([$id,$title,'storage/project-documents/'.$id.'/'.$stored,$f['name'],$mime,$f['size'],$visibility]);header('Location: project-delivery.php?id='.$id);exit;}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Upload Document</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="card mx-auto" style="max-width:650px"><div class="card-body"><h1 class="h4">Upload Project Document</h1><p class="text-muted"><?=$p['name']?></p><form method="post" enctype="multipart/form-data"><label class="form-label">Title</label><input class="form-control mb-3" name="title" required><label class="form-label">Visibility</label><select class="form-select mb-3" name="visibility"><option value="client">Client can access</option><option value="admin">Admin only</option></select><label class="form-label">File</label><input class="form-control mb-2" type="file" name="document" required><div class="form-text mb-3">PDF, Office documents, images and ZIP. Maximum 10MB.</div><button class="btn btn-dark">Upload</button> <a class="btn btn-outline-secondary" href="project-delivery.php?id=<?=$id?>">Cancel</a></form></div></div></main></body></html>